 export default function LegalFooter({ locale = "ar" }: { locale?: string }) {
   const isAr = locale !== "en";
   return (
     <footer style={{
       padding: "24px 16px",
       borderTop: "1px solid #e5e5e5",
       backgroundColor: "#f9fafb",
       textAlign: "center"
     }}>
       <div style={{ display: "flex", justifyContent: "center", gap: 20, marginBottom: 16 }}>
         <a href="https://twitter.com/layali_kashtat" target="_blank" rel="noopener noreferrer" style={{ color: "#1DA1F2" }} aria-label="Twitter">
           <Twitter size={24} />
         </a>
         <a href="https://instagram.com/layali_kashtat" target="_blank" rel="noopener noreferrer" style={{ color: "#E1306C" }} aria-label="Instagram">
           <Instagram size={24} />
         </a>
         <a href="https://www.snapchat.com/add/layalikashtat" target="_blank" rel="noopener noreferrer" style={{ color: "#000" }} aria-label="Snapchat">
           <SnapchatIcon size={24} />
         </a>
       </div>
 
       <div style={{ display: "flex", justifyContent: "center", gap: 16, marginBottom: 16, fontSize: 13, flexWrap: "wrap" }}>
         <a href={`/${locale}/privacy`} style={{ color: "#555", textDecoration: "none" }}>
           {isAr ? "سياسة الخصوصية" : "Privacy Policy"}
         </a>
         <span style={{ color: "#ddd" }}>|</span>
         <a href={`/${locale}/terms`} style={{ color: "#555", textDecoration: "none" }}>
           {isAr ? "الشروط والأحكام" : "Terms of Service"}
         </a>
       </div>
       
       <div style={{ fontSize: 13, color: "#666" }}>
         © {new Date().getFullYear()} ليالي كشتات | Layali Kashtat
       </div>
       
       <div style={{ fontSize: 12, color: "#999", marginTop: 8, borderTop: "1px solid #eee", paddingTop: 8, width: "100%" }}>
         تطوير وتشغيل: <span style={{ fontWeight: 700, color: "#555" }}>حسن خميس الشمري</span>
       </div>
     </footer>
   );
 }
